/**
 * Builds the records an anonymous "Try demo" visitor's account is seeded
 * with, from the synthetic Koperasi Siswa Maju bundle
 * (src/data/koperasiSiswaMaju.json, generated by
 * ml/scenarios/koperasi_siswa_maju.py). Pure: the service does the writes.
 *
 * Dates are moved forward by WHOLE WEEKS so the data ends within the week
 * before the visit. Whole weeks keep every weekday pattern intact; the
 * shift is reported so the page can say so. Nothing else is changed.
 */
import { addDays, daysBetween } from './prepPlanner.js'

export const DEMO_PLATFORM = 'Google Reviews'
export const DEMO_SOURCE = 'fixture_seed'

export const DEMO_PROFILE = Object.freeze({
  business_name: 'Koperasi Siswa Maju (demo)',
  business_type: 'Student cooperative: cafe and mini mart',
  location: 'University campus, Malaysia',
  business_stage: 'Operating',
  target_customer: 'Students and campus staff',
})

/** Whole-week shift that moves `lastDate` to the latest date strictly before `today`. Never negative. */
export function weekShift(lastDate, today) {
  const gap = daysBetween(lastDate, today) // >= 1 means lastDate is before today
  if (gap <= 1) return 0
  return Math.floor((gap - 1) / 7) * 7
}

const money = (v) => v.toFixed(2)

/**
 * @param {object} bundle the parsed koperasiSiswaMaju.json
 * @param {{today: string}} opts ISO date of the visit
 * @returns {{sales: object[], reviews: object[], shiftDays: number, from: string, to: string}}
 */
export function buildDemoRecords(bundle, { today }) {
  const items = new Map(bundle.items.map((i) => [i.item, i]))
  const lastDate = bundle.sales.reduce((max, [d]) => (d > max ? d : max), '')
  const shiftDays = weekShift(lastDate, today)
  const move = (d) => addDays(d, shiftDays)

  const sales = bundle.sales.map(([date, item, units]) => {
    const meta = items.get(item)
    return {
      date: move(date),
      product: item,
      category: meta.section,
      quantity_sold: String(units),
      unit_price: money(meta.unitPrice),
      revenue: money(units * meta.unitPrice),
      discount: '0',
      cost: money(units * meta.unitCost), // line total, as the sales template expects
      shelf_life_days: String(meta.shelfLifeDays),
    }
  })

  const reviews = bundle.reviews.map(([date, , rating, , item, text]) => ({
    date: move(date),
    product: item,
    review_text: text,
    rating: String(rating),
    platform: DEMO_PLATFORM,
  }))

  const dates = sales.map((s) => s.date).sort()
  return { sales, reviews, shiftDays, from: dates[0], to: dates[dates.length - 1] }
}
